-- ----------------------------
-- Table structure for SysJobTrigger
-- ----------------------------
DROP TABLE IF EXISTS `SysJobTrigger`;
CREATE TABLE `SysJobTrigger`  (
  `Id` bigint(20) NOT NULL COMMENT '主键Id',
  `TriggerId` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '触发器Id',
  `JobId` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '作业Id',
  `TriggerType` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '触发器类型',
  `AssemblyName` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '程序集',
  `Args` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '参数',
  `Description` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '描述信息',
  `Status` int(11) NOT NULL COMMENT '状态',
  `StartTime` datetime NULL DEFAULT NULL COMMENT '起始时间',
  `EndTime` datetime NULL DEFAULT NULL COMMENT '结束时间',
  `LastRunTime` datetime NULL DEFAULT NULL COMMENT '最近运行时间',
  `NextRunTime` datetime NULL DEFAULT NULL COMMENT '下一次运行时间',
  `NumberOfRuns` bigint(20) NOT NULL COMMENT '触发次数',
  `MaxNumberOfRuns` bigint(20) NOT NULL COMMENT '最大触发次数',
  `NumberOfErrors` bigint(20) NOT NULL COMMENT '出错次数',
  `MaxNumberOfErrors` bigint(20) NOT NULL COMMENT '最大出错次数',
  `NumRetries` int(11) NOT NULL COMMENT '重试次数',
  `RetryTimeout` int(11) NOT NULL COMMENT '重试间隔时间(ms)',
  `StartNow` tinyint(1) NOT NULL COMMENT '是否立即启动',
  `RunOnStart` tinyint(1) NOT NULL COMMENT '是否启动时执行一次',
  `ResetOnlyOnce` tinyint(1) NOT NULL COMMENT '是否重置触发次数',
  `UpdatedTime` datetime NULL DEFAULT NULL COMMENT '更新时间',
  PRIMARY KEY (`Id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统作业触发器表' ROW_FORMAT = Dynamic;

