  INDEX `index_SysTemplate_G`(`GroupName`) USING BTREE,
  INDEX `index_SysTemplate_CT`(`CreateTime`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统模板表' ROW_FORMAT = Dynamic;

