DROP TABLE IF EXISTS `SysTenant`;
CREATE TABLE `SysTenant`  (
  `Id` bigint(20) NOT NULL COMMENT '主键Id',
  `UserId` bigint(20) NOT NULL COMMENT '租管用户Id',
  `OrgId` bigint(20) NOT NULL COMMENT '机构Id',
  `Host` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '域名',
  `TenantType` int(11) NOT NULL COMMENT '租户类型',
  `DbType` int(11) NOT NULL COMMENT '数据库类型',
  `Connection` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '数据库连接',
  `ConfigId` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '数据库标识',
  `SlaveConnections` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT '从库连接/读写分离',
  `EnableReg` int(11) NULL DEFAULT NULL COMMENT '启用注册功能',
  `RegWayId` bigint(20) NULL DEFAULT NULL COMMENT '默认注册方案',
  `Logo` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '图标',
  `Title` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '标题',
  `ViceTitle` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '副标题',
  `ViceDesc` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '副描述',
  `Watermark` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '水印',
  `Copyright` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '版权信息',
  `Icp` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'ICP备案号',
  `IcpUrl` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'ICP地址',
  `OrderNo` int(11) NOT NULL COMMENT '排序',
  `Remark` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `Status` int(11) NOT NULL COMMENT '状态',
  `CreateTime` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `UpdateTime` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `CreateUserId` bigint(20) NULL DEFAULT NULL COMMENT '创建者Id',
  `CreateUserName` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建者姓名',
  `UpdateUserId` bigint(20) NULL DEFAULT NULL COMMENT '修改者Id',
  `UpdateUserName` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '修改者姓名',
  PRIMARY KEY (`Id`) USING BTREE,
  INDEX `index_SysTenant_CT`(`CreateTime`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统租户表' ROW_FORMAT = Dynamic;

