  `MenuId` bigint(20) NOT NULL COMMENT '菜单Id',
  PRIMARY KEY (`Id`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统用户菜单快捷导航表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of SysUserMenu
-- ----------------------------

-- ----------------------------
-- Table structure for SysUserRegWay
-- ----------------------------
DROP TABLE IF EXISTS `SysUserRegWay`;
CREATE TABLE `SysUserRegWay`  (
  `Id` bigint(20) NOT NULL COMMENT '主键Id',
  `Name` varchar(32) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '方案名称',
  `AccountType` int(11) NOT NULL COMMENT '账号类型',
  `RoleId` bigint(20) NOT NULL COMMENT '角色',
  `OrgId` bigint(20) NOT NULL COMMENT '机构',
  `PosId` bigint(20) NOT NULL COMMENT '职位',
  `OrderNo` int(11) NOT NULL COMMENT '排序',
  `Remark` varchar(128) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `TenantId` bigint(20) NULL DEFAULT NULL COMMENT '租户Id',
  `CreateTime` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `UpdateTime` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `CreateUserId` bigint(20) NULL DEFAULT NULL COMMENT '创建者Id',
  `CreateUserName` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建者姓名',
  `UpdateUserId` bigint(20) NULL DEFAULT NULL COMMENT '修改者Id',
  `UpdateUserName` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '修改者姓名',
  PRIMARY KEY (`Id`) USING BTREE,
  INDEX `index_SysUserRegWay_CT`(`CreateTime`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统用户注册方案表' ROW_FORMAT = Dynamic;

