-- ----------------------------
-- Table structure for SysWechatPay
-- ----------------------------
DROP TABLE IF EXISTS `SysWechatPay`;
CREATE TABLE `SysWechatPay`  (
  `Id` bigint(20) NOT NULL COMMENT '主键Id',
  `MerchantId` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '微信商户号',
  `AppId` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '服务商AppId',
  `OutTradeNumber` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '商户订单号',
  `TransactionId` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '支付订单号',
  `TradeType` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易类型',
  `TradeState` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易状态',
  `TradeStateDescription` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易状态描述',
  `BankType` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款银行类型',
  `Total` int(11) NOT NULL COMMENT '订单总金额',
  `PayerTotal` int(11) NULL DEFAULT NULL COMMENT '用户支付金额',
  `SuccessTime` datetime NULL DEFAULT NULL COMMENT '支付完成时间',
  `ExpireTime` datetime NULL DEFAULT NULL COMMENT '交易结束时间',
  `Description` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '商品描述',
  `Scene` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '场景信息',
  `Attachment` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '附加数据',
  `GoodsTag` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '优惠标记',
  `Settlement` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '结算信息',
  `NotifyUrl` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '回调通知地址',
  `Remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `OpenId` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '微信OpenId标识',
  `Tags` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '业务标签，用来区分做什么业务',
  `BusinessId` bigint(20) NOT NULL COMMENT '对应业务的主键',
  `QrcodeContent` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '付款二维码内容',
  `SubMerchantId` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '子商户号',
  `SubAppId` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '回调通知地址',
  `SubOpenId` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '子商户唯一标识',
  `CreateTime` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `UpdateTime` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `CreateUserId` bigint(20) NULL DEFAULT NULL COMMENT '创建者Id',
  `CreateUserName` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建者姓名',
  `UpdateUserId` bigint(20) NULL DEFAULT NULL COMMENT '修改者Id',
  `UpdateUserName` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '修改者姓名',
  PRIMARY KEY (`Id`) USING BTREE,
  INDEX `index_SysWechatPay_BU`(`BusinessId`) USING BTREE,
  INDEX `index_SysWechatPay_TR`(`TradeState`) USING BTREE,
  INDEX `index_SysWechatPay_TA`(`Tags`) USING BTREE,
  INDEX `index_SysWechatPay_CT`(`CreateTime`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统微信支付表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of SysWechatPay
-- ----------------------------

-- ----------------------------
-- Table structure for SysWechatRefund
-- ----------------------------
DROP TABLE IF EXISTS `SysWechatRefund`;
CREATE TABLE `SysWechatRefund`  (
  `Id` bigint(20) NOT NULL COMMENT '主键Id',
  `WechatPayId` bigint(20) NOT NULL COMMENT '定单主键',
  `OutRefundNumber` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '商户退款号',
  `TransactionId` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT '退款订单号',
  `Reason` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款原因',
  `Channel` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款渠道',
  `UserReceivedAccount` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款入账账户',
  `TradeState` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '退款状态',
  `TradeStateDescription` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '交易状态描述',
  `Refund` int(11) NOT NULL COMMENT '退款金额',
  `SuccessTime` datetime NULL DEFAULT NULL COMMENT '完成时间',
  `NotifyUrl` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '回调通知地址',
  `Remark` varchar(255) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '备注',
  `CreateTime` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `UpdateTime` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `CreateUserId` bigint(20) NULL DEFAULT NULL COMMENT '创建者Id',
  `CreateUserName` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建者姓名',
  `UpdateUserId` bigint(20) NULL DEFAULT NULL COMMENT '修改者Id',
  `UpdateUserName` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '修改者姓名',
  PRIMARY KEY (`Id`) USING BTREE,
  INDEX `index_SysWechatRefund_W`(`WechatPayId`) USING BTREE,
  INDEX `index_SysWechatRefund_CT`(`CreateTime`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统微信支付退款表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of SysWechatRefund
-- ----------------------------

-- ----------------------------
-- Table structure for SysWechatUser
-- ----------------------------
DROP TABLE IF EXISTS `SysWechatUser`;
CREATE TABLE `SysWechatUser`  (
  `Id` bigint(20) NOT NULL COMMENT '主键Id',
  `UserId` bigint(20) NOT NULL COMMENT '系统用户Id',
  `PlatformType` int(11) NOT NULL COMMENT '平台类型',
  `OpenId` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NOT NULL COMMENT 'OpenId',
  `SessionKey` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '会话密钥',
  `UnionId` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT 'UnionId',
  `NickName` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '昵称',
  `Avatar` varchar(256) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '头像',
  `Mobile` varchar(16) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '手机号码',
  `Sex` int(11) NULL DEFAULT NULL COMMENT '性别',
  `Language` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '语言',
  `City` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '城市',
  `Province` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '省',
  `Country` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '国家',
  `AccessToken` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT 'AccessToken',
  `RefreshToken` longtext CHARACTER SET utf8 COLLATE utf8_general_ci NULL COMMENT 'RefreshToken',
  `ExpiresIn` int(11) NULL DEFAULT NULL COMMENT 'ExpiresIn',
  `Scope` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '授权作用域',
  `CreateTime` datetime NULL DEFAULT NULL COMMENT '创建时间',
  `UpdateTime` datetime NULL DEFAULT NULL COMMENT '更新时间',
  `CreateUserId` bigint(20) NULL DEFAULT NULL COMMENT '创建者Id',
  `CreateUserName` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '创建者姓名',
  `UpdateUserId` bigint(20) NULL DEFAULT NULL COMMENT '修改者Id',
  `UpdateUserName` varchar(64) CHARACTER SET utf8 COLLATE utf8_general_ci NULL DEFAULT NULL COMMENT '修改者姓名',
  PRIMARY KEY (`Id`) USING BTREE,
  INDEX `index_SysWechatUser_N`(`NickName`) USING BTREE,
  INDEX `index_SysWechatUser_M`(`Mobile`) USING BTREE,
  INDEX `index_SysWechatUser_CT`(`CreateTime`) USING BTREE
) ENGINE = InnoDB CHARACTER SET = utf8 COLLATE = utf8_general_ci COMMENT = '系统微信用户表' ROW_FORMAT = Dynamic;

-- ----------------------------
-- Records of SysWechatUser
-- ----------------------------

SET FOREIGN_KEY_CHECKS = 1;
